import React, { useState } from 'react';
import { Play, AlertCircle } from 'lucide-react';

interface InteractiveVideoProps {
  id: string; // ScreenPal ID
  aspectRatio?: string;
  coverImage?: string; // Optional custom cover
  title?: string;
}

const InteractiveVideo: React.FC<InteractiveVideoProps> = ({ id, aspectRatio = "56.25%", coverImage, title }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState(false);

  const handlePlay = () => {
    setIsPlaying(true);
  };

  const handleError = () => {
    setError(true);
  };

  if (error) {
    return (
      <div className="w-full h-full bg-slate-900 flex flex-col items-center justify-center border border-slate-700 rounded-lg aspect-video">
        <AlertCircle className="w-10 h-10 text-red-500 mb-2" />
        <span className="text-slate-400 text-sm">Video Unavailable</span>
      </div>
    );
  }

  return (
    <div className="relative w-full rounded-lg overflow-hidden bg-slate-900 shadow-lg border border-slate-800" style={{ paddingTop: aspectRatio }}>
      {!isPlaying ? (
        <div 
          className="absolute inset-0 z-10 cursor-pointer group"
          onClick={handlePlay}
        >
          {/* Cover / Placeholder */}
          {coverImage ? (
            <img src={coverImage} alt={title || "Video thumbnail"} className="w-full h-full object-cover opacity-80 group-hover:opacity-60 transition-opacity duration-300" />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-slate-800 to-slate-900 flex items-center justify-center opacity-90 group-hover:opacity-100 transition-opacity">
               <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
            </div>
          )}

          {/* Play Button Overlay */}
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-16 h-16 bg-neon-cyan/90 rounded-full flex items-center justify-center shadow-[0_0_20px_rgba(34,211,238,0.5)] group-hover:scale-110 transition-transform duration-300">
              <Play className="w-8 h-8 text-black ml-1 fill-black" />
            </div>
          </div>

          <div className="absolute bottom-4 left-4 bg-black/60 px-3 py-1 rounded text-xs text-white backdrop-blur-sm">
            Tap to Play
          </div>
        </div>
      ) : (
        <div className="absolute inset-0 w-full h-full">
            <iframe 
                src={`https://go.screenpal.com/player/${id}?ff=1&title=0&controls=0&autoplay=1`}
                width="100%" 
                height="100%" 
                style={{ border: 0 }} 
                allowFullScreen={true}
                allow="autoplay"
                onError={handleError}
                title={title || "Video Player"}
            />
        </div>
      )}
    </div>
  );
};

export default InteractiveVideo;

import React, { useEffect, useState, useRef } from 'react';

interface AnimatedCounterProps {
  end: number;
  duration?: number;
  suffix?: string;
  label: string;
  icon: React.ReactNode;
}

const AnimatedCounter: React.FC<AnimatedCounterProps> = ({ end, duration = 2000, suffix = '', label, icon }) => {
  const [count, setCount] = useState(0);
  const elementRef = useRef<HTMLDivElement>(null);
  const hasAnimated = useRef(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !hasAnimated.current) {
          hasAnimated.current = true;
          let startTime: number | null = null;
          const step = (timestamp: number) => {
            if (!startTime) startTime = timestamp;
            const progress = Math.min((timestamp - startTime) / duration, 1);
            setCount(Math.floor(progress * end));
            if (progress < 1) {
              window.requestAnimationFrame(step);
            }
          };
          window.requestAnimationFrame(step);
        }
      },
      { threshold: 0.3 }
    );

    if (elementRef.current) {
      observer.observe(elementRef.current);
    }

    return () => {
      if (elementRef.current) observer.unobserve(elementRef.current);
    };
  }, [end, duration]);

  return (
    <div ref={elementRef} className="flex flex-col items-center p-6 bg-slate-900/50 border border-slate-800 rounded-xl hover:border-neon-cyan/30 transition-all duration-300 group">
      <div className="mb-4 text-neon-cyan p-3 bg-neon-cyan/10 rounded-full group-hover:scale-110 transition-transform">
        {icon}
      </div>
      <div className="text-4xl font-bold font-tech text-white mb-2">
        {count.toLocaleString()}{suffix}
      </div>
      <div className="text-slate-400 text-sm font-medium uppercase tracking-wider text-center">
        {label}
      </div>
    </div>
  );
};

export default AnimatedCounter;

import React, { useEffect } from 'react';
import { X } from 'lucide-react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  children: React.ReactNode;
}

const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div 
        className="absolute inset-0 bg-black/80 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />
      <div className="relative bg-slate-900 border border-slate-700 w-full max-w-lg rounded-2xl shadow-[0_0_50px_rgba(0,0,0,0.5)] flex flex-col max-h-[90vh] animate-float">
        <div className="flex items-center justify-between p-5 border-b border-slate-800">
          <h3 className="text-xl font-bold font-tech text-white">{title}</h3>
          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-full transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
        <div className="p-6 overflow-y-auto custom-scrollbar">
          {children}
        </div>
      </div>
    </div>
  );
};

export default Modal;

