import React, { useState } from 'react';
import { Play, AlertCircle } from 'lucide-react';

interface InteractiveVideoProps {
  id: string; // ScreenPal ID or Direct URL
  aspectRatio?: string;
  coverImage?: string; // Optional custom cover
  title?: string;
}

const InteractiveVideo: React.FC<InteractiveVideoProps> = ({ id, aspectRatio = "56.25%", coverImage, title }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState(false);

  const handlePlay = () => {
    setIsPlaying(true);
  };

  const handleError = () => {
    setError(true);
  };

  const isMp4 = id.toLowerCase().endsWith('.mp4') || id.startsWith('http');

  if (error) {
    return (
      <div className="w-full h-full bg-slate-900 flex flex-col items-center justify-center border border-slate-700 rounded-lg aspect-video">
        <AlertCircle className="w-10 h-10 text-red-500 mb-2" />
        <span className="text-slate-400 text-sm">Video Unavailable</span>
      </div>
    );
  }

  return (
    <div className="relative w-full rounded-lg overflow-hidden bg-slate-900 shadow-lg border border-slate-800" style={{ paddingTop: aspectRatio }}>
      {!isPlaying ? (
        <div 
          className="absolute inset-0 z-10 cursor-pointer group"
          onClick={handlePlay}
        >
          {/* Cover / Placeholder */}
          {coverImage ? (
            <img src={coverImage} alt={title || "Video thumbnail"} className="w-full h-full object-cover opacity-80 group-hover:opacity-60 transition-opacity duration-300" />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-slate-800 to-slate-900 flex items-center justify-center opacity-90 group-hover:opacity-100 transition-opacity">
               <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
            </div>
          )}

          {/* Play Button Overlay */}
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-16 h-16 bg-neon-cyan/90 rounded-full flex items-center justify-center shadow-[0_0_20px_rgba(34,211,238,0.5)] group-hover:scale-110 transition-transform duration-300">
              <Play className="w-8 h-8 text-black ml-1 fill-black" />
            </div>
          </div>

          <div className="absolute bottom-4 left-4 bg-black/60 px-3 py-1 rounded text-xs text-white backdrop-blur-sm">
            Tap to Play
          </div>
        </div>
      ) : (
        <div className="absolute inset-0 w-full h-full">
            {isMp4 ? (
                <video
                    className="w-full h-full object-cover"
                    controls
                    autoPlay
                    playsInline
                    onError={handleError}
                >
                    <source src={id} type="video/mp4" />
                    Your browser does not support the video tag.
                </video>
            ) : (
                <iframe 
                    src={`https://go.screenpal.com/player/${id}?ff=1&title=0&controls=0&autoplay=1`}
                    width="100%" 
                    height="100%" 
                    style={{ border: 0 }} 
                    allowFullScreen={true}
                    allow="autoplay"
                    onError={handleError}
                    title={title || "Video Player"}
                />
            )}
        </div>
      )}
    </div>
  );
};

