import React, { useState, useRef } from 'react';
import { Play, AlertCircle } from 'lucide-react';

interface InteractiveVideoProps {
  id: string; // ScreenPal ID or Direct URL
  aspectRatio?: string;
  coverImage?: string; // Optional custom cover
  title?: string;
}

const InteractiveVideo: React.FC<InteractiveVideoProps> = ({ id, aspectRatio = "56.25%", coverImage, title }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  const handlePlay = () => {
    setIsPlaying(true);
    if (videoRef.current) {
      videoRef.current.play();
    }
  };

  const handleError = () => {
    setError(true);
  };

  const isMp4 = id.toLowerCase().endsWith('.mp4') || id.startsWith('http');

  // Append #t=0.001 to force browser to seek to the first frame for thumbnail (safe for most modern browsers)
  const videoSrc = isMp4 && !id.includes('#t=') ? `${id}#t=0.001` : id;

  if (error) {
    return (
      <div className="w-full h-full bg-slate-900 flex flex-col items-center justify-center border border-slate-700 rounded-lg aspect-video">
        <AlertCircle className="w-10 h-10 text-red-500 mb-2" />
        <span className="text-slate-400 text-sm">Video Unavailable</span>
      </div>
    );
  }

  // MP4 Handler
  if (isMp4) {
    return (
      <div className="relative w-full rounded-lg overflow-hidden bg-slate-900 shadow-lg border border-slate-800 group" style={{ paddingTop: aspectRatio }}>
        <div className="absolute inset-0 w-full h-full">
            <video
                ref={videoRef}
                className={`w-full h-full ${isPlaying ? 'object-contain bg-black' : 'object-cover'}`}
                playsInline
                controls={isPlaying}
                loop
                muted={!isPlaying} 
                preload="metadata"
                onPlay={() => setIsPlaying(true)}
                onPause={() => setIsPlaying(false)}
                onError={handleError}
                poster={coverImage}
            >
                <source src={videoSrc} type="video/mp4" />
                Your browser does not support the video tag.
            </video>
        </div>

        {/* Overlay for MP4 */}
        {!isPlaying && (
            <div 
                className="absolute inset-0 z-20 cursor-pointer bg-black/20 hover:bg-black/40 transition-colors duration-300 flex items-center justify-center"
                onClick={handlePlay}
            >
                <div className="w-16 h-16 bg-neon-cyan/90 rounded-full flex items-center justify-center shadow-[0_0_20px_rgba(34,211,238,0.5)] group-hover:scale-110 transition-transform duration-300 backdrop-blur-sm">
                    <Play className="w-8 h-8 text-black ml-1 fill-black" />
                </div>
                <div className="absolute bottom-4 left-4 bg-black/60 px-3 py-1 rounded text-xs text-white backdrop-blur-sm font-medium">
                    Tap to Play
                </div>
            </div>
        )}
      </div>
    );
  }

  // ScreenPal / Iframe Handler
  // We render iframe immediately to show its native thumbnail, but block pointer events initially so our overlay works?
  // Actually, ScreenPal players usually handle click-to-play well. 
  // But to ensure "thumbnails appear", we must render the iframe.
  return (
    <div className="relative w-full rounded-lg overflow-hidden bg-slate-900 shadow-lg border border-slate-800" style={{ paddingTop: aspectRatio }}>
        <div className="absolute inset-0 w-full h-full">
            <iframe 
                src={`https://go.screenpal.com/player/${id}?ff=1&title=0&controls=0&autoplay=0`}
                width="100%" 
                height="100%" 
                style={{ border: 0 }} 
                allowFullScreen={true}
                allow="autoplay"
                onError={handleError}
                title={title || "Video Player"}
            />
        </div>

        {/* Optional: Add a custom overlay that disappears on click if we want consistent styling.
            However, enabling the iframe allows the user to see the native player thumbnail.
            If we place a div on top, we might block the native play button.
            Let's rely on the native player thumbnail for ScreenPal but ensure it's loaded.
        */}
    </div>
  );
};

export default InteractiveVideo;

