                src={`https://go.screenpal.com/player/${id}?ff=1&title=0&controls=0&autoplay=1&muted=1`}
                width="100%" 
                height="100%" 
                style={{ border: 0 }} 
                allowFullScreen={true}
                allow="autoplay"
                onError={handleError}
                title={title || "Video Player"}
            />
        </div>
    </div>
  );
};

