import React, { useState, useRef } from 'react';
import { Play, AlertCircle } from 'lucide-react';

interface InteractiveVideoProps {
  id: string; // ScreenPal ID or Direct URL
  aspectRatio?: string;
  coverImage?: string; // Optional custom cover
  title?: string;
}

const InteractiveVideo: React.FC<InteractiveVideoProps> = ({ id, aspectRatio = "56.25%", coverImage, title }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  const handlePlay = () => {
    setIsPlaying(true);
    if (videoRef.current) {
      videoRef.current.play();
    }
  };

  const handleError = () => {
    setError(true);
  };

  const isMp4 = id.toLowerCase().endsWith('.mp4') || id.startsWith('http');
  const videoSrc = isMp4 && !id.includes('#t=') ? `${id}#t=0.001` : id;

  if (error) {
    return (
      <div className="w-full h-full bg-slate-100 dark:bg-slate-900 flex flex-col items-center justify-center border border-slate-200 dark:border-slate-700 rounded-lg aspect-video">
        <AlertCircle className="w-10 h-10 text-red-500 mb-2" />
        <span className="text-slate-500 dark:text-slate-400 text-sm">Video Unavailable</span>
      </div>
    );
  }

  // MP4 Handler
  if (isMp4) {
    return (
      <div className="relative w-full rounded-lg overflow-hidden bg-black shadow-lg border border-slate-200 dark:border-slate-800 group" style={{ paddingTop: aspectRatio }}>
        <div className="absolute inset-0 w-full h-full">
            <video
                ref={videoRef}
                className={`w-full h-full ${isPlaying ? 'object-contain bg-black' : 'object-cover'}`}
                playsInline
                controls={isPlaying}
                loop={false}
                muted={false} 
                preload="metadata"
                onPlay={() => setIsPlaying(true)}
                onPause={() => setIsPlaying(false)}
                onError={handleError}
                poster={coverImage}
            >
                <source src={videoSrc} type="video/mp4" />
                Your browser does not support the video tag.
            </video>
        </div>

        {/* Overlay - Only visible when not playing */}
        {!isPlaying && (
            <div 
                className="absolute inset-0 z-20 cursor-pointer bg-black/20 hover:bg-black/40 transition-colors duration-300 flex items-center justify-center"
                onClick={handlePlay}
            >
                <div className="w-16 h-16 bg-white/90 dark:bg-neon-cyan/90 rounded-full flex items-center justify-center shadow-lg dark:shadow-[0_0_20px_rgba(34,211,238,0.5)] group-hover:scale-110 transition-transform duration-300 backdrop-blur-sm">
                    <Play className="w-8 h-8 text-black ml-1 fill-black" />
                </div>
            </div>
        )}
      </div>
    );
  }

  // ScreenPal / Iframe Handler
  return (
    <div className="relative w-full rounded-lg overflow-hidden bg-black shadow-lg border border-slate-200 dark:border-slate-800" style={{ paddingTop: aspectRatio }}>
        {!isPlaying && (
           <div 
             className="absolute inset-0 z-20 cursor-pointer bg-black/20 hover:bg-black/40 transition-colors duration-300 flex items-center justify-center"
             onClick={() => setIsPlaying(true)}
           >
              <div className="w-16 h-16 bg-white/90 dark:bg-neon-cyan/90 rounded-full flex items-center justify-center shadow-lg dark:shadow-[0_0_20px_rgba(34,211,238,0.5)] transition-transform duration-300 backdrop-blur-sm">
                  <Play className="w-8 h-8 text-black ml-1 fill-black" />
              </div>
           </div>
        )}
        <div className="absolute inset-0 w-full h-full">
            <iframe 
                src={`https://go.screenpal.com/player/${id}?ff=1&title=0&controls=1&autoplay=${isPlaying ? 1 : 0}`}
                width="100%" 
                height="100%" 
                style={{ border: 0 }} 
                allowFullScreen={true}
                allow="autoplay"
                onError={handleError}
                title={title || "Video Player"}
            />
        </div>
    </div>
  );
};

export default InteractiveVideo;

import React, { useEffect, useState, useRef } from 'react';

interface AnimatedCounterProps {
  end: number;
  duration?: number;
  suffix?: string;
  label: string;
  icon: React.ReactNode;
}

const AnimatedCounter: React.FC<AnimatedCounterProps> = ({ end, duration = 2000, suffix = '', label, icon }) => {
  const [count, setCount] = useState(0);
  const elementRef = useRef<HTMLDivElement>(null);
  const hasAnimated = useRef(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !hasAnimated.current) {
          hasAnimated.current = true;
          let startTime: number | null = null;
          const step = (timestamp: number) => {
            if (!startTime) startTime = timestamp;
            const progress = Math.min((timestamp - startTime) / duration, 1);
            setCount(Math.floor(progress * end));
            if (progress < 1) {
              window.requestAnimationFrame(step);
            }
          };
          window.requestAnimationFrame(step);
        }
      },
      { threshold: 0.3 }
    );

    if (elementRef.current) {
      observer.observe(elementRef.current);
    }

    return () => {
      if (elementRef.current) observer.unobserve(elementRef.current);
    };
  }, [end, duration]);

  return (
    <div ref={elementRef} className="flex flex-col items-center p-6 bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl hover:border-cyan-400 dark:hover:border-neon-cyan/30 transition-all duration-300 group shadow-md dark:shadow-none">
      <div className="mb-4 text-cyan-600 dark:text-neon-cyan p-3 bg-cyan-50 dark:bg-neon-cyan/10 rounded-full group-hover:scale-110 transition-transform">
        {icon}
      </div>
      <div className="text-4xl font-bold font-tech text-slate-900 dark:text-white mb-2">
        {count.toLocaleString()}{suffix}
      </div>
      <div className="text-slate-500 dark:text-slate-400 text-sm font-medium uppercase tracking-wider text-center">
        {label}
      </div>
    </div>
  );
};

export default AnimatedCounter;

import React, { useEffect } from 'react';
import { X } from 'lucide-react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  children: React.ReactNode;
}

const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div 
        className="absolute inset-0 bg-slate-900/80 dark:bg-black/80 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />
      <div className="relative bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 w-full max-w-lg rounded-2xl shadow-2xl dark:shadow-[0_0_50px_rgba(0,0,0,0.5)] flex flex-col max-h-[90vh] animate-float">
        <div className="flex items-center justify-between p-5 border-b border-slate-100 dark:border-slate-800">
          <h3 className="text-xl font-bold font-tech text-slate-900 dark:text-white">{title}</h3>
          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
        <div className="p-6 overflow-y-auto custom-scrollbar">
          {children}
        </div>
      </div>
    </div>
  );
};

