  const [theme, setTheme] = useState<'dark' | 'light'>('dark');

  // Theme Toggle Logic
  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  // Dynamic Title
  useEffect(() => {
    const titles = {
      [PageState.HOME]: "AILM - Turn Ideas into Visuals",
      [PageState.ABOUT]: "About Us - AILM",
      [PageState.CONTACT]: "Contact - AILM",
      [PageState.TERMS]: "Terms - AILM",
      [PageState.REFUND]: "Refund Policy - AILM",
      [PageState.SHIPPING]: "Delivery Info - AILM"
    };
    document.title = titles[activePage];
    window.scrollTo(0, 0);
  }, [activePage]);

  const navigateTo = (page: PageState) => {
    setActivePage(page);
    setMobileMenuOpen(false);
  };

