    switch (activePage) {
      case PageState.HOME: return renderHome();
      case PageState.ABOUT: return <AboutPage />;
      case PageState.CONTACT: return <ContactPage />;
      case PageState.TERMS: return <LegalPage title="Terms of Service" content={TERMS_CONTENT} />;
      case PageState.REFUND: return <LegalPage title="Refund Policy" content={REFUND_CONTENT} />;
      case PageState.SHIPPING: return <LegalPage title="Delivery Information" content={SHIPPING_CONTENT} />;
