                <div className="p-6 pt-0 text-slate-600 dark:text-slate-400 leading-relaxed border-t border-slate-50 dark:border-slate-800/50">
                   {faq.a}
                </div>
              </details>
            ))}
          </div>
        </div>
      </section>

      {/* Final CTA */}
      <section className="py-24 px-4 relative">
        <div className="absolute inset-0 bg-slate-900 dark:bg-white -z-10"></div>
        <div className="max-w-4xl mx-auto text-center">
           <h2 className="text-5xl md:text-7xl font-black text-white dark:text-slate-950 mb-8 font-tech leading-tight">Ready to Dominate the Digital Space?</h2>
           <p className="text-slate-400 dark:text-slate-600 text-lg md:text-xl mb-12">Join 1,400+ brands scaling their growth with AI-powered creative assets.</p>
           <button 
             onClick={() => setIsOrderModalOpen(true)}
             className="px-12 py-6 bg-cyan-500 hover:bg-cyan-400 text-white font-black text-xl rounded-full transition-all hover:scale-105 active:scale-95 shadow-[0_0_30px_rgba(34,211,238,0.4)]"
           >
             Start Your Project Now
           </button>
        </div>
      </section>
    </main>
  );

  const renderContent = () => {
    switch (activePage) {
      case PageState.HOME: return renderHome();
      case PageState.ABOUT: return <AboutPage />;
      case PageState.CONTACT: return <ContactPage />;
      case PageState.TERMS: return <LegalPage title="Terms of Service" content={TERMS_CONTENT} />;
      case PageState.REFUND: return <LegalPage title="Refund Policy" content={REFUND_CONTENT} />;
      case PageState.SHIPPING: return <LegalPage title="Delivery Information" content={SHIPPING_CONTENT} />;
      default: return renderHome();
    }
  };

  return (
    <div className="min-h-screen bg-white dark:bg-slate-950 font-sans transition-colors duration-300">
      <Header />
      {renderContent()}
      <Footer />
      <OrderModal isOpen={isOrderModalOpen} onClose={() => setIsOrderModalOpen(false)} />

      {/* Floating CTA */}
      <div className="fixed bottom-8 right-8 z-30">
        <button 
          onClick={() => setIsOrderModalOpen(true)}
          className="group relative p-4 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-full shadow-2xl hover:scale-110 active:scale-95 transition-all"
        >
          <div className="absolute -top-12 right-0 bg-slate-800 text-white text-[10px] font-bold px-3 py-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
            Need a video?
          </div>
          <Zap className="w-8 h-8 fill-current" />
        </button>
      </div>
    </div>
  );
};

