          </div>
        </div>
      </section>

      {/* FAQ Section */}
      <section id="faqs" className="py-24 px-4 bg-slate-50 dark:bg-slate-950/50">
        <div className="max-w-3xl mx-auto">
           <div className="text-center mb-16">
