import React, { useState, useRef, useEffect } from 'react';
import { AlertCircle, Play } from 'lucide-react';

interface InteractiveVideoProps {
  id: string; // ScreenPal ID or Direct URL
  aspectRatio?: string;
  coverImage?: string; // Optional custom cover
  title?: string;
}

const InteractiveVideo: React.FC<InteractiveVideoProps> = ({ id, aspectRatio = "56.25%", coverImage: propCoverImage, title }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  const isMp4 = id.toLowerCase().endsWith('.mp4') || (id.startsWith('http') && !id.includes('screenpal.com'));
  const videoSrc = isMp4 && !id.includes('#t=') ? `${id}#t=0.001` : id;

  // Faster thumbnail logic
  const getThumbnailUrl = () => {
    if (propCoverImage) return propCoverImage;
    if (!isMp4) {
      // Use ScreenPal screenshot API for instant high-quality thumbnails
      const screenPalId = id.includes('screenpal.com/player/') ? id.split('player/')[1] : id;
      return `https://screenshot.screenpal.com/get/image?id=${screenPalId}&w=720`;
    }
    return null; // For MP4, preloaded metadata handles first frame
  };

  const coverImage = getThumbnailUrl();

  // Handle auto-playing MP4s on state change
  useEffect(() => {
    if (isPlaying && videoRef.current) {
      const playPromise = videoRef.current.play();
      if (playPromise !== undefined) {
        playPromise.catch(err => {
          console.warn("Playback prevented:", err);
        });
      }
    }
  }, [isPlaying]);

  const handlePlayClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsPlaying(true);
  };

  const handleError = () => {
    setError(true);
  };

  if (error) {
    return (
      <div className="w-full h-full bg-slate-100 dark:bg-slate-900 flex flex-col items-center justify-center border border-slate-200 dark:border-slate-700 rounded-lg aspect-video">
        <AlertCircle className="w-10 h-10 text-red-500 mb-2" />
        <span className="text-slate-500 dark:text-slate-400 text-sm">Video Unavailable</span>
      </div>
    );
  }

  // Determine the final ID for ScreenPal if a URL was passed
  const cleanId = id.includes('screenpal.com/player/') ? id.split('player/')[1] : id;

  return (
    <div className="relative w-full rounded-lg overflow-hidden bg-black shadow-lg border border-slate-200 dark:border-slate-800 group" style={{ paddingTop: aspectRatio }}>

      {/* 1. Placeholder / Overlay State - Fast Loading & Single Tap Interaction */}
      {!isPlaying && (
        <div 
          className="absolute inset-0 z-30 cursor-pointer transition-all duration-300 flex items-center justify-center group/play"
          onClick={handlePlayClick}
        >
          {coverImage ? (
            <img 
              src={coverImage} 
              alt={title || "Video preview"} 
              loading="lazy"
              className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover/play:scale-105"
              onError={(e) => { (e.target as HTMLImageElement).style.display = 'none'; }}
            />
          ) : (
            <div className="absolute inset-0 bg-gradient-to-br from-slate-900 to-black opacity-80" />
          )}

          <div className="absolute inset-0 bg-black/0 group-hover/play:bg-black/20 transition-colors duration-300" />

          {/* Centered Play Button - Premium Glassmorphism */}
          <div className="relative z-10 w-16 h-16 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center border border-white/30 group-hover/play:scale-110 group-hover/play:bg-white/40 transition-all duration-300 shadow-2xl">
            <Play className="w-7 h-7 text-white fill-white ml-1" />
          </div>
        </div>
      )}

      {/* 2. Active Video Content */}
      <div className="absolute inset-0 w-full h-full">
        {isPlaying ? (
          isMp4 ? (
            <video
              ref={videoRef}
              className="w-full h-full object-contain bg-black"
              playsInline
              controls
              autoPlay
              onPlay={() => setIsPlaying(true)}
              onError={handleError}
            >
              <source src={videoSrc} type="video/mp4" />
            </video>
          ) : (
            <iframe 
              src={`https://go.screenpal.com/player/${cleanId}?ff=1&title=0&controls=1&autoplay=1`}
              width="100%" 
              height="100%" 
              style={{ border: 0 }} 
              allowFullScreen={true}
              allow="autoplay; fullscreen; picture-in-picture"
              onError={handleError}
              title={title || "Video Player"}
            />
          )
        ) : (
          isMp4 ? (
            <video className="w-full h-full object-cover" preload="metadata" muted playsInline>
              <source src={videoSrc} type="video/mp4" />
            </video>
          ) : (
            <div className="w-full h-full bg-black" />
          )
        )}
      </div>
    </div>
  );
};

